const itemIndex = $itemIndex;
const rawItem = $items("3. Filter Global Tech News")[itemIndex]?.json || $items("3. Filter Global Tech News")[0]?.json || {};

let aiRes = null;
try {
  const contentRaw = $json.choices?.[0]?.message?.content || '{}';
  aiRes = JSON.parse(contentRaw);
} catch (e) {
  aiRes = null;
}

if (!aiRes || !aiRes.title) {
  const fallbackTitle = (rawItem.rawTitle || 'تحولات امنیت سایبری و شبکه').slice(0, 80);
  const fallbackDesc = rawItem.rawDesc || 'گزارش تحلیلی پیرامون فناوری و امنیت اینترنت';
  aiRes = {
    title: fallbackTitle,
    slug: '',
    summary: fallbackDesc.slice(0, 160),
    content: (rawItem.rawDesc || fallbackDesc) + '\n\n' + 'این گزارش از منابع بین‌المللی فناوری استخراج شده است.',
    meta_title: fallbackTitle.slice(0, 60),
    meta_description: fallbackDesc.slice(0, 160)
  };
}

// Clean and sanitize slug
const cleanTitle = (aiRes.title || rawItem.rawTitle || 'global-news').trim();
const sourceIdentifier = (rawItem.sourceName || 'global').trim();
const combinedForHash = (cleanTitle + '|' + sourceIdentifier).toLowerCase();

let hash = 0;
for (let i = 0; i < combinedForHash.length; i++) {
  hash = ((hash << 5) - hash) + combinedForHash.charCodeAt(i);
  hash |= 0;
}
const hashString = Math.abs(hash).toString(36);

let baseSlug = (aiRes.slug || cleanTitle)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '');

if (!baseSlug || baseSlug.length < 3) {
  baseSlug = 'global-security-news';
}

const finalSlug = (baseSlug.substring(0, 45) + '-' + hashString).replace(/--+/g, '-');

// Append SEO Source
const sourceName = rawItem.sourceName || 'منبع بین‌المللی';
const sourceLink = rawItem.rawLink || 'https://etesal.aetherai.ir';
const finalContent = (aiRes.content || rawItem.rawDesc || '') + '\n\n---\n🌐 **منبع اصلی خبر:** [' + sourceName + '](' + sourceLink + ')';

return [{
  json: {
    title: aiRes.title || cleanTitle,
    slug: finalSlug,
    summary: aiRes.summary || (rawItem.rawDesc || '').slice(0, 160),
    content: finalContent,
    meta_title: (aiRes.meta_title || aiRes.title || cleanTitle).slice(0, 60),
    meta_description: (aiRes.meta_description || aiRes.summary || '').slice(0, 160),
    image_url: null,
    is_published: true,
    published_at: new Date().toISOString()
  }
}];
